    .filter((c) => c.edition)
    .sort((a, b) => {
      // Running or upcoming before finished; then soonest.
      const past = (c) => (c.edition.lastDate < today ? 1 : 0);
      return past(a) - past(b) || a.edition.firstDate.localeCompare(b.edition.firstDate);
