"use strict";
const { jerusalemReady, plannerReady, calendarDays } = require("../../shared/case-helpers");

/* Choosing another festival on the timeline: the calendar becomes its run and
 * a day either side, the address names it, and the page opens on it again. */
module.exports = {
  description: "choosing a festival on the timeline sets the period to its run plus a day either side, and the address names it",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    const jerusalem = await calendarDays(page);
    assert.equal(jerusalem[0], "2026-10-17", "Jerusalem runs from the 18th: the calendar opens the day before");
    assert.equal(jerusalem[jerusalem.length - 1], "2026-10-23", "and closes the day after the 22nd");

    await page.click('.tl-item[data-festival="haifa-iff"]');
    await plannerReady(page, "haifa-iff");
    const haifa = await calendarDays(page);
    assert.equal(haifa[0], "2026-09-24", "Haifa runs from 25 Sep: the day before");
    assert.equal(haifa[haifa.length - 1], "2026-10-04", "to 3 Oct: the day after");
    assert.equal(haifa.length, 11, "every day between, one column each");

    const url = new URL(page.url());
    assert.equal(url.searchParams.get("festival"), "haifa-iff", "the address names the festival");
    assert.equal(
      await page.getAttribute('.tl-item[data-festival="haifa-iff"]', "aria-pressed"),
      "true",
      "the chosen bar is the pressed one"
    );

    // The last choice is what a plain /planNG/ opens on next time.
    await page.goto(`${origin}/planNG/`, { waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    assert.equal((await calendarDays(page))[0], "2026-09-24", "the page reopens on the festival chosen last");

    // And the address alone focuses a festival, whatever was chosen before.
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);
    assert.equal((await calendarDays(page))[0], "2026-10-17", "?festival= wins over the stored choice");
  },
};
"use strict";
const { jerusalemReady, calendarDays, JERUSALEM_EDITION } = require("../../shared/case-helpers");

/* The calendar's two ends each add a day, the added days are remembered for
 * the festival, and the period stops growing at its cap. */
module.exports = {
  description: "the period extends a day at a time from either end, is remembered, and stops at its cap",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    const { MAX_PERIOD_DAYS } = await import("../../../../site/shared/limits.js");
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    await page.click("#periodEarlier");
    await jerusalemReady(page);
    await page.click("#periodLater");
    await jerusalemReady(page);
    const days = await calendarDays(page);
    assert.equal(days[0], "2026-10-16", "a day before the day before");
    assert.equal(days[days.length - 1], "2026-10-24", "and a day after the day after");

    const prefs = await page.evaluate(() => JSON.parse(localStorage.getItem("planNG.prefs")));
    assert.deepEqual(prefs.periods[JERUSALEM_EDITION], { from: "2026-10-16", to: "2026-10-24" }, "the period is stored for this festival");

    await page.reload({ waitUntil: "load" });
    await jerusalemReady(page);
    assert.equal((await calendarDays(page))[0], "2026-10-16", "and comes back on a reload");

    // A period at the cap offers no more days at either end.
    await page.evaluate(
      ([key, periods]) => {
        const p = JSON.parse(localStorage.getItem("planNG.prefs"));
        p.periods = { [key]: periods };
        localStorage.setItem("planNG.prefs", JSON.stringify(p));
      },
      [JERUSALEM_EDITION, { from: "2026-10-01", to: `2026-10-${String(MAX_PERIOD_DAYS).padStart(2, "0")}` }]
    );
    await page.reload({ waitUntil: "load" });
    await jerusalemReady(page);
    assert.equal((await calendarDays(page)).length, MAX_PERIOD_DAYS, "the stored period at the cap is drawn whole");
    assert.equal(await page.isDisabled("#periodEarlier"), true, "no earlier day past the cap");
    assert.equal(await page.isDisabled("#periodLater"), true, "no later day past the cap");
  },
};
"use strict";
const fs = require("node:fs");
const path = require("node:path");
const { jerusalemReady } = require("../../shared/case-helpers");

const REGISTRY = path.join(__dirname, "..", "..", "shared", "fixtures", "data", "festivals", "index.json");

// A festival 4,000 km away running in the middle of Jerusalem's: it carries a
// real programme (Jerusalem's own block, so it has shows to leak), and none of
// them may reach the calendar. The registry is the fixture's plus this one, and
// nothing else about the page is touched.
