.flight--out .flight-plane {
  transform: rotate(45deg);
}
.flight--back .flight-plane {
  transform: rotate(135deg);
}
[dir="rtl"] .flight--out .flight-plane {
  transform: rotate(-45deg);
}
[dir="rtl"] .flight--back .flight-plane {
  transform: rotate(-135deg);
}
.flight-title {
