    ["Jerusalem, 18 – 22 Oct", "Edinburgh, 10 – 30 Oct", "4000 km", "10 – 16 Oct and 24 – 30 Oct"],
    ["Jerusalem, 18 – 22 Oct", "Edinburgh, 19 – 21 Oct", "4000 km", "none"],
