/* The reader's trip: the first and last day the page plans, as rules.
 *
 * The trip is the reader's own, set on the timeline; a festival is only a
 * shortcut to its run. Which festival leads a trip — whose theme the page
 * wears and whose city reach is judged from — is the one the reader chose
 * while the trip still reaches it, and otherwise follows from the dates.
 *
 * Pure: no DOM, no storage.
 */

import { daysOf, shiftDay } from "./pool.js";
import { editionKey } from "./timeline.js";

const ISO = /^\d{4}-\d{2}-\d{2}$/;

/** A festival edition's run and a day either side, for getting there and back. */
export function tripForEdition(edition) {
  return { from: shiftDay(edition.firstDate, -1), to: shiftDay(edition.lastDate, 1) };
}

/**
 * A trip made whole: ends in order, no longer than `maxDays`, inside `span`.
 * @param {{from: string, to: string}} trip
 * @param {object} o
 * @param {"from"|"to"|null} o.moved the end the reader just set, which holds
 *   while the other one gives way; null holds the first day
 * @param {number} o.maxDays
 * @param {{from: string, to: string}} [o.span] the days the timeline shows
 */
export function normalizeTrip({ from, to }, { moved = null, maxDays, span = null }) {
  if (from > to) [from, to] = [to, from];
  if (span) {
    from = from < span.from ? span.from : from > span.to ? span.to : from;
    to = to < span.from ? span.from : to > span.to ? span.to : to;
  }
  if (daysOf(from, to).length > maxDays) {
    if (moved === "to") from = shiftDay(to, -(maxDays - 1));
    else to = shiftDay(from, maxDays - 1);
  }
  return { from, to };
}

/** The trip a query string names, or null: `?from=&to=`. */
export function tripFromQuery(params) {
  const from = params.get("from");
  const to = params.get("to");
  return from && to && ISO.test(from) && ISO.test(to) ? { from, to } : null;
}

/**
 * The edition that leads a trip: the one the reader chose (`pick`, an edition
 * key) while the trip overlaps its run; otherwise the one the trip covers most
 * days of, the earlier start breaking a tie; with none inside it, the nearest
 * by date.
 * @param {{festivals: object[]}} registry
 * @param {{from: string, to: string, pick?: string|null}} trip
 * @returns {{festival: object, edition: object}|null}
 */
export function leadEdition(registry, { from, to, pick = null }) {
  let best = null;
  for (const festival of registry.festivals) {
    for (const edition of festival.editions) {
      const lo = edition.firstDate > from ? edition.firstDate : from;
      const hi = edition.lastDate < to ? edition.lastDate : to;
      const overlap = lo <= hi ? daysOf(lo, hi).length : 0;
      if (overlap && pick === editionKey(festival.id, edition.id)) return { festival, edition };
      // How far off an edition that misses the trip is, in days; 0 if it overlaps.
      const gap = overlap
        ? 0
        : edition.lastDate < from
          ? daysOf(edition.lastDate, from).length - 1
          : daysOf(to, edition.firstDate).length - 1;
      const score = { festival, edition, overlap, gap };
      if (
        !best ||
        score.overlap > best.overlap ||
        (score.overlap === best.overlap && score.gap < best.gap) ||
        (score.overlap === best.overlap && score.gap === best.gap && edition.firstDate < best.edition.firstDate)
      ) {
        best = score;
      }
    }
  }
  return best ? { festival: best.festival, edition: best.edition } : null;
}

import { test } from "node:test";
import assert from "node:assert/strict";

import { leadEdition, normalizeTrip, tripForEdition, tripFromQuery } from "../trip.js";

const registry = {
  festivals: [
    { id: "big", editions: [{ id: "2026", firstDate: "2026-09-25", lastDate: "2026-10-03" }] },
    { id: "small", editions: [{ id: "2026", firstDate: "2026-09-27", lastDate: "2026-10-01" }] },
    { id: "later", editions: [{ id: "2026", firstDate: "2026-10-18", lastDate: "2026-10-22" }] },
  ],
};

test("a festival's trip is its run and a day either side", () => {
  assert.deepEqual(tripForEdition({ firstDate: "2026-10-18", lastDate: "2026-10-22" }), { from: "2026-10-17", to: "2026-10-23" });
});

test("a trip's ends are put in order", () => {
  assert.deepEqual(normalizeTrip({ from: "2026-10-05", to: "2026-10-01" }, { maxDays: 31 }), { from: "2026-10-01", to: "2026-10-05" });
});

test("a trip past the cap pulls the end that was not moved", () => {
  assert.deepEqual(normalizeTrip({ from: "2026-10-01", to: "2026-11-15" }, { moved: "to", maxDays: 31 }), { from: "2026-10-16", to: "2026-11-15" });
  assert.deepEqual(normalizeTrip({ from: "2026-10-01", to: "2026-11-15" }, { moved: "from", maxDays: 31 }), { from: "2026-10-01", to: "2026-10-31" });
  assert.deepEqual(normalizeTrip({ from: "2026-10-01", to: "2026-11-15" }, { maxDays: 31 }), { from: "2026-10-01", to: "2026-10-31" });
  // Exactly the cap is left alone.
  assert.deepEqual(normalizeTrip({ from: "2026-10-01", to: "2026-10-31" }, { moved: "to", maxDays: 31 }), { from: "2026-10-01", to: "2026-10-31" });
});

test("a trip is held inside the days the timeline shows", () => {
  const span = { from: "2026-08-01", to: "2027-07-31" };
  assert.deepEqual(normalizeTrip({ from: "2026-07-20", to: "2026-08-03" }, { maxDays: 31, span }), { from: "2026-08-01", to: "2026-08-03" });
  assert.deepEqual(normalizeTrip({ from: "2027-07-30", to: "2027-08-09" }, { maxDays: 31, span }), { from: "2027-07-30", to: "2027-07-31" });
});

test("the address names a trip only with two dates", () => {
  assert.deepEqual(tripFromQuery(new URLSearchParams("from=2026-10-01&to=2026-10-04")), { from: "2026-10-01", to: "2026-10-04" });
  assert.equal(tripFromQuery(new URLSearchParams("from=2026-10-01")), null);
  assert.equal(tripFromQuery(new URLSearchParams("from=soon&to=later")), null);
});

test("the edition a trip covers most leads it", () => {
  assert.equal(leadEdition(registry, { from: "2026-09-24", to: "2026-10-04" }).festival.id, "big");
  assert.equal(leadEdition(registry, { from: "2026-10-02", to: "2026-10-20" }).festival.id, "later");
});

test("a tie on days covered goes to the edition that starts first", () => {
  assert.equal(leadEdition(registry, { from: "2026-09-28", to: "2026-10-01" }).festival.id, "big");
});

test("a trip over no festival is led by the nearest one", () => {
  assert.equal(leadEdition(registry, { from: "2026-10-12", to: "2026-10-14" }).festival.id, "later");
  assert.equal(leadEdition(registry, { from: "2026-10-05", to: "2026-10-06" }).festival.id, "big");
  assert.equal(leadEdition({ festivals: [] }, { from: "2026-10-05", to: "2026-10-06" }), null);
});

test("the festival the reader chose leads while the trip reaches it", () => {
  // "small" is inside "big"'s run, so on days covered alone it would never lead.
  assert.equal(leadEdition(registry, { from: "2026-09-26", to: "2026-10-02", pick: "small@2026" }).festival.id, "small");
  assert.equal(leadEdition(registry, { from: "2026-09-30", to: "2026-10-01", pick: "small@2026" }).festival.id, "small", "down to its last shared day");
  assert.equal(leadEdition(registry, { from: "2026-10-02", to: "2026-10-20", pick: "small@2026" }).festival.id, "later", "and not once the trip has left it");
});

/* The flights either side of a trip, as rules: which airport a reader flies
 * from, which currency to quote them, and the one call to the site's own fare
 * service (api/fares.js), which is the only thing that talks to the partner.
 *
 * No DOM. `fetchFares` takes its fetch as an argument so the rule for what a
 * failure means is testable without a network.
 */

/* The main airport — or the city code that covers all of a city's airports —
 * for each country the origin question names. A reader can overwrite it; a
 * country not listed leaves it for them to type. */
export const COUNTRY_AIRPORTS = {
  GB: "LON",
  US: "NYC",
  FR: "PAR",
  DE: "BER",
  RU: "MOW",
  UA: "KBP",
  IT: "ROM",
  ES: "MAD",
  NL: "AMS",
  PL: "WAW",
  JP: "TYO",
  CA: "YTO",
  AU: "SYD",
  IL: "TLV",
};

const COUNTRY_CURRENCIES = { GB: "gbp", US: "usd", JP: "jpy", CA: "cad", AU: "aud", PL: "pln", RU: "rub", UA: "uah", IL: "ils" };
const DEFAULT_CURRENCY = "eur";

/** An IATA airport or city code as the reader typed it, or null. */
export function airportCode(text) {
  const code = String(text || "").trim().toUpperCase();
  return /^[A-Z]{3}$/.test(code) ? code : null;
}

/** The airport a reader flies from: the one they typed, else their country's. */
export function originAirport(origin) {
  if (!origin) return null;
  return airportCode(origin.airport) || (origin.country && COUNTRY_AIRPORTS[origin.country]) || null;
}

/** The currency to quote a reader in, lower-case as the fare service takes it. */
export function fareCurrency(origin) {
  return (origin && origin.country && COUNTRY_CURRENCIES[origin.country]) || DEFAULT_CURRENCY;
}

/** The fare service's address for one day's flights on one route. */
export function faresUrl({ from, to, dateISO, currency }) {
  const q = new URLSearchParams({ from, to, date: dateISO, currency });
  return `/api/fares?${q}`;
}

/**
 * The cheapest flights for one day, or an empty list. An answer that is not a
 * list of fares — a failed request, a service that isn't there, a body that
 * doesn't parse — is the same to the reader as no fares: nothing claims a
 * price, and the block offers the search instead.
 * @returns {Promise<{departAt: string, durationMin: number|null, stops: number|null,
 *   price: number, currency: string, airline: string|null, link: string}[]>}
 */
export async function fetchFares(fetchImpl, params) {
  try {
    const res = await fetchImpl(faresUrl(params));
    if (!res.ok) return [];
    const body = await res.json();
    const fares = body && Array.isArray(body.fares) ? body.fares : [];
    return fares.filter((f) => f && typeof f.departAt === "string" && Number.isFinite(f.price) && typeof f.link === "string");
  } catch {
    return [];
  }
}

